// Generated from geoBoundaries gbOpen LKA ADM2 (OpenStreetMap, ODbL 1.0).
// Boundaries simplified to ~0.55px for inline rendering; do not use for navigation.
// Regenerate rather than hand-editing.

export interface DistrictShape {
  /** District name as used by the API, e.g. "Nuwara Eliya" */
  name: string;
  /** URL slug, e.g. "nuwara-eliya" */
  slug: string;
  /** ISO 3166-2 code, e.g. "LK-42" */
  iso: string;
  /** Label anchor in viewBox units */
  cx: number;
  cy: number;
  /** SVG path data */
  d: string;
}

export const MAP_VIEWBOX = '0 0 620 1088';
export const MAP_WIDTH = 620;
export const MAP_HEIGHT = 1088;

/** Equirectangular fit used to draw the paths above. */
export const PROJECTION = {
  minLon: 79.6510158,
  maxLat: 9.8357907,
  /** cos(mean latitude) — corrects longitude spacing. */
  kx: 0.99056359,
  scale: 273.684517,
  pad: 8,
} as const;

/** Projects a real coordinate into viewBox units. */
export function projectPoint(lat: number, lon: number): { x: number; y: number } {
  return {
    x: (lon - PROJECTION.minLon) * PROJECTION.kx * PROJECTION.scale + PROJECTION.pad,
    y: (PROJECTION.maxLat - lat) * PROJECTION.scale + PROJECTION.pad,
  };
}

